  const opt = (k: 'batched' | 'at-mint', t: string, x: string) => `<label class="ldopt ${st.copyMode === k ? 'on' : ''}"><input type="radio" name="copyMode" value="${k}" ${st.copyMode === k ? 'checked' : ''}><b>${t}</b><span class="mut small">${x}</span></label>`;
  return `<div class="gh">Escrow copies</div><div class="ldopts two">${opt('batched', 'Batched <span class="ldtag mc">Default</span>', `Base queues the copies and sends one LayerZero message per chain per batch. ≈ $${share.toFixed(2)} per NFT on Base.`)}${opt('at-mint', 'At every mint', `Copies are sent with each mint. Copies land within minutes, but ≈ $${atMint.toFixed(2)}+ per mint.`)}</div>
   ${b ? `<div class="ldbatch">${inp('batchK', `Batch size K <span class="mut small">IDs per batch, ${BATCH.minK}-${BATCH.maxK} (default ${BATCH.defaultK})</span>`, `type="number" min="${BATCH.minK}" max="${BATCH.maxK}"`)}${inp('batchT', `Batch window T <span class="mut small">minutes after the oldest queued ID, ${BATCH.minTMin}-${BATCH.maxTMin} (default ${BATCH.defaultTMin})</span>`, `type="number" min="${BATCH.minTMin}" max="${BATCH.maxTMin}"`)}</div>
   <p class="mut small">A batch goes out when K IDs are queued or T minutes after the oldest one, whichever comes first (and right away at sell-out). Anyone can trigger it; it's paid from a small per-mint share that the contract keeps for this drop. Unused batch buffer left at the end goes to MultiSea (it is not taken from your proceeds). NFTs are Active on the minter's chain right away; only the escrow copies wait. Larger K means a cheaper share but a longer wait on slow days.</p>` : ''}`;
